using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.Query; using Xunit;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Query;
public sealed class AstronomyKnowledgeDomainFilterTests{[Fact]public void Constructs_and_normalizes(){var caller=new List<AstronomyKnowledgeDomain>{AstronomyKnowledgeDomain.Orbital,AstronomyKnowledgeDomain.Physical,AstronomyKnowledgeDomain.Physical};var f=new AstronomyKnowledgeDomainFilter(caller);caller.Add(AstronomyKnowledgeDomain.Orbital);Assert.Equal(AstronomyKnowledgeQueryMatchMode.Any,f.MatchMode);Assert.Equal(new[]{AstronomyKnowledgeDomain.Physical,AstronomyKnowledgeDomain.Orbital},f.Values);Assert.Throws<NotSupportedException>(()=>((IList<AstronomyKnowledgeDomain>)f.Values).Add(AstronomyKnowledgeDomain.Physical));}[Fact]public void Supports_all_mode(){var f=new AstronomyKnowledgeDomainFilter([AstronomyKnowledgeDomain.Physical],AstronomyKnowledgeQueryMatchMode.All);Assert.Equal(AstronomyKnowledgeQueryMatchMode.All,f.MatchMode);}[Fact]public void Rejects_invalid_inputs(){Assert.Throws<ArgumentException>(()=>new AstronomyKnowledgeDomainFilter([]));Assert.Throws<ArgumentOutOfRangeException>(()=>new AstronomyKnowledgeDomainFilter([(AstronomyKnowledgeDomain)99]));Assert.Throws<ArgumentOutOfRangeException>(()=>new AstronomyKnowledgeDomainFilter([AstronomyKnowledgeDomain.Physical],(AstronomyKnowledgeQueryMatchMode)99));}}
